  FT["PH-H10160"] = {"id":"PH-H10160","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11732_2022.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Feng Li菲律宾公民身份、使其归化为菲律宾公民的法案","en":"An Act Granting Philippine Citizenship to Feng Li","orig":"An Act Granting Philippine Citizenship to Feng Li"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 11732","issuingBody":"Congress of the Philippines","promulgatedDate":"2022-04-29","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2022/ra_11732_2022.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10160-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Mr. Feng Li hereby granted Philippine citizenship wit all the rights, privileges and prerogatives as well as the duties and obligations appurtenant thereto under the Constitution and the laws of the Republic of the Philippines."}},{"id":"PH-H10160-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Mr. Feng Li shall take the Oath of Allegiance to the Republic of the Philippines before an officer duly authorized to administer the same. The Oath of Allegiance shall be registered with the Bureau of Immigration."}},{"id":"PH-H10160-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Upon registration of the Oath of Allegiance, the Bureau of Immigration shall issue a Certificate of Naturalization to Mr.Feng Li who shall thereupon enter into the full enjoynment of Philippine citizenship."}},{"id":"PH-H10160-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in the newspaper of general circulation."}}],"pack":"ph-p144","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Philippine Citizenship to Feng Li","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H10161"] = {"id":"PH-H10161","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11733_2022.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Patrick Francois Rebucci菲律宾公民身份、使其归化为菲律宾公民的法案","en":"An Act Granting Philippine Citizenship to Patrick Francois Rebucci","orig":"An Act Granting Philippine Citizenship to Patrick Francois Rebucci"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 11733","issuingBody":"Congress of the Philippines","promulgatedDate":"2022-04-29","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2022/ra_11733_2022.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10161-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Mr.Patrick Francois Renucci is hereby granted Philippine citizenship with all the rights, priveleges and prerogatives, as well as the duties and obligations appurtenant thereto under the Constitution and the laws of the Republic of the Philippines."}},{"id":"PH-H10161-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Mr.Renucci shall take the Oath of Allegiance to the Republic of the Philippines before an officer duly authorized to administer the same. The Oath of Allegiance shall be registered with the Bureau of Immigration."}},{"id":"PH-H10161-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Upon registration of the Oath of Allegiance, the Bureau of Immigration shall issue a Certificate of Naturalization to Mr.Renucci who shall thereupon enter into the full enjoynment of Philippine citizenship."}},{"id":"PH-H10161-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in the newspaper of general circulation."}}],"pack":"ph-p144","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Philippine Citizenship to Patrick Francois Rebucci","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H10162"] = {"id":"PH-H10162","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11734_2022.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"设立Puerto Princesa市","en":"An Act Establishing a Central Multi-Species Marine Hatchery in the City Environmental Estate in Barangay Sta. Lucia, City of Puerto Princesa, Province of Palawan, and Appropriating Funds Therefor","orig":"An Act Establishing a Central Multi-Species Marine Hatchery in the City Environmental Estate in Barangay Sta. Lucia, City of Puerto Princesa, Province of Palawan, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["environment","administrative"],"docNumber":"Republic Act No. 11734","issuingBody":"Congress of the Philippines","promulgatedDate":"2022-04-27","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2022/ra_11734_2022.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10162-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the supervision of the Bureau of Fisheries and Aquatic Resources of the Department of Agriculture (BFAR-DA), a central multi-species marine hatchery in the City Environmental Estate in Barangay Sta. Lucia, City of Puerto Princesa, Province of Palawan."}},{"id":"PH-H10162-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The BFAR-DA shall transfer the management of the central multi-species marine hatchery to the Western Philippines University (WPU) within five (5) years after its construction through a memorandum of agreement. With the assistance of the Southeast Asian Fisheries Development Center Aquaculture Division, the BFAR-DA shall implement a training and phasing-in program for WPU personnel on the management and operation of the central hatchery."}},{"id":"PH-H10162-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The BFAR-DA and the WPU shall develop an extension program which shall cater to marginal fisherfolk to educate them on new methods and technology especially on the propagation of high-value marine species."}},{"id":"PH-H10162-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Agriculture shall include in the Department's programs the establishment of the central multi-species marine hatchery in the City Environmental Estate in Barangay Sta. Lucia, City of Puerto Princesa, Province of Palawan, the funding of which shall be included in the annual General Appropriations Act. The WPU shall set aside funds from any available revenue in an amount deemed appropriate for the operationalization of the central hatchery."}},{"id":"PH-H10162-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Within sixty (60) days from the passage of this Act, the Secretary of Agriculture shall issue the rules and regulations on the supervision, operation, monitoring, and the eventual transfer of the management of the multi-species marine hatchery to the WPU."}},{"id":"PH-H10162-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p144"};
  FT["PH-H10163"] = {"id":"PH-H10163","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11735_2022.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Batad市","en":"An Act Establishing a Satellite Multi-Species Marine Hatchery in the Municipality of Batad, Province of Iloilo and Appropriating Funds Therefor","orig":"An Act Establishing a Satellite Multi-Species Marine Hatchery in the Municipality of Batad, Province of Iloilo and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11735","issuingBody":"Congress of the Philippines","promulgatedDate":"2022-04-27","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2022/ra_11735_2022.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10163-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Bureau of Fisheries and Aquatic Resources of the Department of Agriculture (BFAR-DA), a satellite multi-species marine hatchery in the Municipality of Batad, Province of Iloilo."}},{"id":"PH-H10163-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The BFAR-DA shall, within three (3) years after the establishment of the satellite multi-species marine hatchery, transfer the management of the same to the Northern Iloilo Polytechnic State College (NIPSCO through a memorandum of agreement. The BFAR-DA shall implement a training and phasing-in program for NIPSC personnel on the management and operation of the satellite multi-species marine hatchery.\nThe BFAR-DA and the NIPSC shall conduct continuing research and experimentation on the breeding and production of marine species, especially as they apply to local conditions, to discover new methods and strategy that shall benefit the fisheries industry."}},{"id":"PH-H10163-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Agriculture shall include in the Department's programs the establishment of the satellite multi-species marine hatchery in the Municipality of Batad, Province of Iloilo, the funding of which shall be included in the annual General Appropriations Act. The NIPSC shall set aside funds from any available revenue in an amount deemed appropriate for the operationalization of the satellite hatchery"}},{"id":"PH-H10163-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Within sixty (60) days from the approval of this Act, the Department of Agriculture and the NIPSC shall issue the rules and regulations on the establishment, supervision, operation, monitoring, and the eventual transfer of the management of the satellite multi-species marine hatchery to the NIPSC."}},{"id":"PH-H10163-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p144"};
  FT["PH-H10164"] = {"id":"PH-H10164","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11736_2022.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Basilisa市","en":"An Act Establishing a Multi-Species Marine Hatcery in the Municipality of Basilisa, Province of Dinagat Islands, and Appropriating Funds Therefor","orig":"An Act Establishing a Multi-Species Marine Hatcery in the Municipality of Basilisa, Province of Dinagat Islands, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11736","issuingBody":"Congress of the Philippines","promulgatedDate":"2022-04-27","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2022/ra_11736_2022.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10164-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Bureau of Fisheries and Aquatic Resources of the Department of Agriculture (BFAR-DA), a multi-species marine hatchery in the Municipality of Basilisa, Province of Dinagat Islands."}},{"id":"PH-H10164-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The BFAR-DA shall transfer the management of the multi-species marine hatchery to the local government of Basilisa, within two (2) years after its construction through a memorandum of agreement. The BFAR-DA shall implement a training and phasing-in program for the personnel of the local government unit concerned on the management and operation of the multi-species marine hatchery.\nThe BFAR-DA shall conduct continuing research and experimentation on the breeding and production of marine species, especially as they apply to local conditions, to discover new methods and strategy that shall benefit the fisheries industry."}},{"id":"PH-H10164-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Agriculture shall include in the Department's programs the establishment of the multi-species marine hatchery in the Municipality of Basilisa, Province of Dinagat Islands, the funding of which shall be included in the annual General Appropriations Act. The local government unit concerned shall set aside funds from any available revenue in an amount deemed appropriate for the operationalization of the hatchery."}},{"id":"PH-H10164-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Within sixty (60) days from the effectivity of this Act, the Secretary of Agriculture shall issue the rules and regulations on the supervision, operation, monitoring, and the eventual transfer of the management of the multi-species marine hatchery to the local government of Basilisa."}},{"id":"PH-H10164-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p144"};
  FT["PH-H10165"] = {"id":"PH-H10165","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11737_2022.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Alicia市","en":"An Act Establishing a Regular District Office of the Land Transportation (LTO) in the Municipality of Alicia, Province of Isabela","orig":"An Act Establishing a Regular District Office of the Land Transportation (LTO) in the Municipality of Alicia, Province of Isabela"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11737","issuingBody":"Congress of the Philippines","promulgatedDate":"2022-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2022/ra_11737_2022.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10165-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a regular district office of the Land Transportation Office (LTO) in the Municipality of Alicia, Province of Isabela."}},{"id":"PH-H10165-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Transportation shall immediately include in the Department's program the operationalization of the LTO-Alicia District Office in the Province of Isabela, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H10165-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in two (2) newspapers of general circulation."}}],"pack":"ph-p144"};
